(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18+Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.016-t*0.22)*18+Math.sin(x*0.014+t*0.28)*12;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*8;
  const w2y = Math.cos((x-y)*0.01-t*0.12)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [120+Math.sin(t*0.5)*100, 60+Math.cos(t*0.35)*40, 0.075, 2.1],
    [360+Math.cos(t*0.45)*90, 80+Math.sin(t*0.6)*50, 0.09, 1.8],
    [200+Math.sin(t*0.3+2)*120, 180+Math.cos(t*0.5+1)*70, 0.06, 2.4],
    [80+Math.cos(t*0.7+1)*70, 200+Math.sin(t*0.55+3)*50, 0.11, 1.6],
    [400+Math.sin(t*0.4+4)*80, 160+Math.cos(t*0.8+2)*60, 0.065, 2.7],
    [280+Math.cos(t*0.32+5)*110, 40+Math.sin(t*0.48)*60, 0.085, 2.0],
    [240+Math.sin(t*0.38+3)*90, 120+Math.cos(t*0.42+2)*80, 0.055, 2.9],
    [160+Math.cos(t*0.55+6)*60, 100+Math.sin(t*0.65+4)*70, 0.095, 1.4],
    [340+Math.sin(t*0.28+1)*100, 200+Math.cos(t*0.52+5)*40, 0.07, 2.2],
    [60+Math.cos(t*0.62+2)*80, 140+Math.sin(t*0.33+1)*90, 0.08, 1.9]
  ];
  let aS=0, iS=0, hS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w=Math.sin(d*0.003-t*0.2)*0.3+1;
    aS+=Math.sin(d*f*w-t*sp);
    iS+=Math.sin(d*f*0.65*w+t*sp*0.55+1.7);
    hS+=Math.cos(d*f*0.4*w-t*sp*0.8+3.1)*0.5;
  }
  const act=aS/10, inh=iS/10, hib=hS/10;
  const bg1=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*0.95))/2;
  const bg2=Math.sin((sx+sy)*0.1+t*2.2)*0.18+Math.sin((sx-sy)*0.085-t*1.8)*0.18;
  const bg3=Math.sin(sx*0.06+Math.sin(sy*0.05+t)*2+t*1.5)*0.12;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.045-ang*3.5-t*1.3);
  const sp2=Math.sin(dist*0.035+ang*4.5-t*1.0);
  const sp3=Math.sin(dist*0.025-ang*2-t*0.7)*Math.cos(ang*5+t*0.5);
  const spiral=(sp1+sp2)*0.3+sp3*0.25;
  const laplacian=Math.sin(sx*0.12+t*0.4)*Math.sin(sy*0.12-t*0.3)+Math.sin((sx*0.08-sy*0.08)+t*0.6)*0.5;
  const rd1=Math.tanh((act-inh*0.65+bg*0.28+spiral+laplacian*0.15)*2.0);
  const rd2=Math.tanh((inh*0.8-act*0.5+hib*0.3+spiral*0.5)*1.8);
  const rdMix=rd1*0.7+rd2*0.3;
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.45+Math.sin(sx*0.07-sy*0.11+t*0.7)*0.3)*1.4)*0.25;
  const micro=Math.sin(sx*0.25+t*3)*Math.sin(sy*0.25-t*2.5)*0.06;
  const blend=rdMix*0.68+cell*0.26+micro, v=blend*0.5+0.5;
  const pal=[
    [6,12,52],[12,42,88],[18,78,115],[24,118,128],
    [45,155,130],[130,185,95],[195,195,60],
    [220,165,55],[215,115,60],[185,65,55],
    [140,35,50],[85,18,48],[40,12,42],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sm=f*f*(3-2*f);
  const lum=0.82+Math.sin(rdMix*Math.PI)*0.18+Math.abs(rd2)*0.05;
  const edge=Math.abs(rdMix)>0.65?1.12:1.0;
  const glow=Math.max(0,1-Math.abs(rdMix)*1.5)*0.08;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum*edge+glow*80)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*lum*edge+glow*120)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*lum*edge+glow*180)|0)
  ];
}
